import {schedule,validate,time,example,envelope} from './schedule.js';
const $=id=>document.getElementById(id), key='arcdrake.rehearsal.v1';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let savedSignature=null;
const signature=()=>JSON.stringify({plan,simulation});
function saveState(){const saved=savedSignature===signature();$('save-state').textContent=saved?'Current event and test settings match your browser save.':'Current event has not been saved, or has changes since your last save. Choose Save in this browser to keep it.';}
let plan=example();let simulation={delayStep:'',delay:0,unavailable:''};
function renderDemo(delayed=false){
 const demoPlan=example(), baseline=schedule(demoPlan), current=schedule(demoPlan,delayed?{delayStep:'demo',delay:10}:{});
 $('demo-baseline').setAttribute('aria-pressed',String(!delayed));$('demo-delay').setAttribute('aria-pressed',String(delayed));
 $('demo-result').innerHTML=`<ol class="demo-timeline">${current.rows.map((r,i)=>`<li class="${r.begin>baseline.rows[i].begin?'changed':''}"><time>${time(r.begin)}</time><span>${escape(r.title)}${r.delay?' · 10 min late':''}</span></li>`).join('')}</ol><div class="demo-finish"><span>${delayed?'Finish moves 10 minutes later':'Planned finish'}</span><strong>${time(current.end)}</strong></div>`;
}
$('hero-delay').onclick=()=>{renderDemo(true);$('demo').scrollIntoView({block:'center'});$('demo-delay').focus({preventScroll:true});};
$('demo-baseline').onclick=()=>renderDemo(false);$('demo-delay').onclick=()=>renderDemo(true);renderDemo();
function askConfirm(message,action='Replace event'){
 const dialog=$('confirm-action');$('confirm-title').textContent=action+'?';$('confirm-message').textContent=message;$('confirm-accept').textContent=action;$('confirm-cancel').textContent=action==='Remove step'?'Keep step':'Keep current event';dialog.returnValue='';
 return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='accept'),{once:true});dialog.showModal();});
}
$('confirm-cancel').onclick=()=>$('confirm-action').close('cancel');$('confirm-accept').onclick=()=>$('confirm-action').close('accept');
function status(s){$('status').textContent=s;}
const options=(items,selected)=>items.map(([value,label])=>`<option value="${escape(value)}" ${value===selected?'selected':''}>${escape(label)}</option>`).join('');
function render(){
 $('title').value=plan.title;$('start').value=plan.start;$('people').value=plan.people.join(', ');
 $('steps').innerHTML=plan.steps.map((s,i)=>`<article class="step" data-id="${escape(s.id)}"><div class="step-head"><span class="number">${i+1}</span><input aria-label="Step ${i+1} name" data-field="title" value="${escape(s.title)}" maxlength="120"><button data-remove="${escape(s.id)}" aria-label="Remove ${escape(s.title)}">Remove</button></div><div class="step-fields"><label>Duration (minutes)<input data-field="duration" type="number" min="1" max="1440" value="${s.duration}"></label><fieldset class="choice-group"><legend>People needed for this step</legend><div class="choices">${plan.people.length?plan.people.map(p=>`<label class="check"><input type="checkbox" data-person="${escape(p)}" ${s.people.includes(p)?'checked':''}>${escape(p)}</label>`).join(''):'<small>Add names under People involved above, then leave that field to assign them here.</small>'}</div></fieldset><label>Notes for the run sheet<textarea data-field="notes" maxlength="2000">${escape(s.notes)}</textarea></label></div><div class="dependencies"><p class="field-help">Select every step that must finish before this one starts. Leave unchecked to allow overlap when people are free.</p><fieldset class="choice-group"><legend>Must wait for these steps</legend><div class="choices">${plan.steps.filter(d=>d.id!==s.id).map(d=>`<label class="check"><input type="checkbox" data-dependency="${escape(d.id)}" ${s.depends.includes(d.id)?'checked':''}>${escape(d.title||'Untitled step')}</label>`).join('')||'<small>No other steps yet. This step can start at the event start time.</small>'}</div></fieldset></div></article>`).join('');
 $('delayStep').innerHTML=options([['','No delay'],...plan.steps.map(s=>[s.id,s.title])],simulation.delayStep);
 $('unavailable').innerHTML=options([['','Everyone available'],...plan.people.map(p=>[p,p])],simulation.unavailable);$('delay').value=simulation.delay;$('delay').disabled=!simulation.delayStep;
 result();
}
function result(){
 saveState();
 const baseline=schedule(plan), current=schedule(plan,simulation);
 let heading=document.getElementById('print-heading');if(!heading){heading=document.createElement('h1');heading.id='print-heading';document.querySelector('.output').prepend(heading);}heading.textContent=plan.title||'Untitled event';
 $('errors').innerHTML=current.errors.length?`<div class="error"><strong>Schedule paused — fix these event steps</strong>${current.errors.map(escape).join('<br>')}</div>`:'';
 if(current.errors.length){$('simulation-context').textContent='The schedule will return when the issues above are fixed.';$('summary').innerHTML='';$('schedule').innerHTML='';return;}
 const drift=current.end-baseline.end, blocked=current.rows.filter(r=>r.blocked).length;
 const delayed=plan.steps.find(s=>s.id===simulation.delayStep);
 $('simulation-context').textContent=`${delayed?simulation.delay>0?delayed.title+' starts '+simulation.delay+' minutes late.':'Choose a delay greater than 0 to test '+delayed.title+'.':'No start delay applied.'} ${simulation.unavailable?simulation.unavailable+' is unavailable for the whole event. Blocked steps cannot proceed; their times and finish are estimates.':'Everyone is available.'}`;
 $('summary').innerHTML=current.rows.length?`<div class="summary"><div class="metric"><strong>${time(current.end)}</strong><span>${blocked?'Estimated finish':'Event finishes at'}</span><small>${blocked?'Includes blocked steps; resolve them before relying on this time.':'End of the last scheduled step.'}</small></div><div class="metric"><strong>${current.end-current.start} min</strong><span>Time from start to finish</span><small>Includes waiting and delays; overlapping steps count once.</small></div><div class="metric"><strong>+${drift} min</strong><span>${blocked?'Estimated change to finish':'Change to finish time'}</span><small>Compared with ${time(baseline.end)} without test changes.</small></div><div class="metric"><strong>${blocked}</strong><span>Steps that cannot proceed</span><small>${blocked?'Need the missing person or a step that is blocked.':'No steps blocked by an unavailable person.'}</small></div></div>`:'';
 $('schedule').innerHTML=current.rows.length?current.rows.map(r=>{const original=baseline.rows.find(b=>b.id===r.id);return `<article class="row ${r.blocked?'blocked':''}"><div class="times">${time(r.begin)}<small>to ${time(r.end)}</small></div><div><h3>${escape(r.title)}</h3><p>${r.duration} min${r.people.length?' · '+r.people.map(escape).join(', '):' · Unassigned (no person required)'}</p>${r.notes?`<p>${escape(r.notes)}</p>`:''}${r.blocked?'<span class="tag">Cannot proceed · missing person or earlier step</span>':''}${r.begin>original.begin?`<span class="tag">+${r.begin-original.begin} min later than without test changes</span>`:''}${r.wait?`<span class="tag">Wait ${r.wait} min for assigned people to be free</span>`:''}${r.delay?`<span class="tag">Simulated delay ${r.delay} min</span>`:''}</div></article>`;}).join(''):'<p class="empty-schedule">No steps yet. Choose <strong>Add a step</strong> in the editor, name the activity, and set its duration. Your schedule will appear here.</p>';
}
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function sheet(){const current=schedule(plan,simulation);if(current.errors.length){status('Resolve the schedule errors before exporting.');return null;}return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(plan.title)} — run sheet</title><style>body{font:15px system-ui;color:#17392d;max-width:1000px;margin:40px auto;padding:20px}h1{font-size:32px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #bbb}td{vertical-align:top}small{display:block;color:#68715e}tr{break-inside:avoid}button{padding:10px}@media print{button{display:none}body{margin:0}}</style><h1>${escape(plan.title||'Untitled event')}</h1><p>${current.rows.some(r=>r.blocked)?'Estimated run sheet — blocked steps need attention':'Run sheet'} · ${time(current.start)}–${time(current.end)} · ${current.end-current.start} minutes</p><p>Test changes: ${simulation.delayStep?escape(plan.steps.find(s=>s.id===simulation.delayStep)?.title)+' delayed '+escape(simulation.delay)+' minutes before starting':'No delay'} · ${simulation.unavailable?escape(simulation.unavailable)+' unavailable for the whole event':'Everyone available'}</p><button onclick="window.print()">Print this run sheet</button><table><thead><tr><th>Time</th><th>Step</th><th>People</th><th>Notes / status</th></tr></thead><tbody>${current.rows.map(r=>`<tr><td>${time(r.begin)}–${time(r.end)}<small>${r.duration} min</small></td><td>${escape(r.title)}</td><td>${r.people.map(escape).join(', ')||'—'}</td><td>${escape(r.notes)}${r.blocked?'<small>BLOCKED · time is an estimate</small>':''}</td></tr>`).join('')}</tbody></table><p><small>Created with Rehearsal by Arcdrake. (+1d) means the next day. Blocked steps cannot proceed until the plan is adjusted; their times are estimates.</small></p></html>`;}
function save(){try{localStorage.setItem(key,JSON.stringify({version:1,plan,simulation,savedAt:new Date().toISOString()}));savedSignature=signature();saveState();status('Saved in this browser. Use Download editable event (.json) for a backup or another device.');}catch{status('This browser could not save. Choose Download editable event (.json) to keep a copy.');}}
async function load(){try{const raw=localStorage.getItem(key);if(!raw){status('No saved event in this browser yet.');return;}const data=envelope(JSON.parse(raw));if(signature()!==JSON.stringify(data)&&!(await askConfirm('This opens your browser save in place of the event and test settings shown. Unsaved changes will be lost.','Open browser save')))return;plan=data.plan;simulation=data.simulation;savedSignature=signature();render();status('Browser save opened.');}catch{status('Saved event could not be read. Your current event is still here.');}}
document.addEventListener('input',e=>{const t=e.target,s=plan.steps.find(s=>s.id===t.closest('.step')?.dataset.id);if(s&&t.dataset.field){s[t.dataset.field]=t.dataset.field==='duration'?Number(t.value):t.value;result();}else if(t.id==='title'){plan.title=t.value;result();}else if(t.id==='start'){plan.start=t.value;result();}else if(t.id==='delay'){simulation.delay=Math.min(1440,Math.max(0,Math.round(Number(t.value)||0)));result();}});
document.addEventListener('change',e=>{const t=e.target,s=plan.steps.find(s=>s.id===t.closest('.step')?.dataset.id);if(s&&(t.dataset.person||t.dataset.dependency)){const field=t.dataset.person?'people':'depends',value=t.dataset.person||t.dataset.dependency;s[field]=t.checked?[...s[field],value]:s[field].filter(v=>v!==value);result();}if(t.id==='people'){plan.people=[...new Set(t.value.split(',').map(p=>p.trim()).filter(Boolean))];plan.steps.forEach(s=>s.people=s.people.filter(p=>plan.people.includes(p)));if(!plan.people.includes(simulation.unavailable))simulation.unavailable='';render();}if(t.id==='delayStep'||t.id==='unavailable'){simulation[t.id]=t.value;$('delay').disabled=!simulation.delayStep;result();}if(t.id==='delay')t.value=simulation.delay;if(t.dataset.field==='title')render();});
document.addEventListener('click',async e=>{const id=e.target.dataset.remove;if(id){const step=plan.steps.find(s=>s.id===id);if(!step)return;const dependents=plan.steps.filter(s=>s.depends.includes(id)).length;if(!(await askConfirm('Remove '+(step.title||'this step')+' from the event?'+(dependents?' '+dependents+' other step(s) will stop waiting for it.':'')+' This does not change your browser save.','Remove step')))return;plan.steps=plan.steps.filter(s=>s.id!==id);plan.steps.forEach(s=>s.depends=s.depends.filter(d=>d!==id));if(simulation.delayStep===id)simulation.delayStep='';render();}});
$('add').onclick=()=>{if(plan.steps.length>=100){status('This event has reached the 100-step limit.');return;}plan.steps.push({id:crypto.randomUUID(),title:'New step',duration:5,people:[],depends:[],notes:''});render();$('steps').lastElementChild.querySelector('input').focus();};
$('reset').onclick=()=>{simulation={delayStep:'',delay:0,unavailable:''};render();status('Test changes cleared. Step names, durations, people, and order are unchanged.');};
$('example').onclick=async()=>{if(plan.steps.length&&!(await askConfirm('The example will replace the event and test settings shown. Save or download a copy first to keep unsaved work.','Replace with example')))return;plan=example();simulation={delayStep:'',delay:0,unavailable:''};savedSignature=null;render();status('Example loaded. Try delaying the live demo by 10 minutes.');};
$('new').onclick=async()=>{if(plan.steps.length&&!(await askConfirm('Start with no steps or people. This replaces the event shown, including test settings. Save or download a copy first to keep unsaved work.','Start empty event')))return;plan={version:1,title:'My event',start:'18:00',people:[],steps:[]};simulation={delayStep:'',delay:0,unavailable:''};savedSignature=null;render();$('title').focus();status('Empty event ready. Set its name and start time, add people, then choose Add a step.');};
$('save').onclick=save;$('reload').onclick=load;$('download').onclick=()=>{download(JSON.stringify({version:1,plan,simulation},null,2),'rehearsal-event.json','application/json');status('Editable event download requested (.json). Open event file (.json) restores its steps and test settings. This does not update your browser save.');};
$('export').onclick=()=>{const html=sheet();if(html){download(html,'rehearsal-run-sheet.html','text/html');status('Run sheet download requested (.html), including the test settings shown. Open it in a browser to read, share, or print. This does not save an editable event.');}};
$('print').onclick=()=>{if(validate(plan).length){status('Resolve the schedule errors before printing.');return;}document.title=(plan.title||'Event')+' — Rehearsal';window.print();};
$('import-button').onclick=()=>$('import').click();
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Event file must be under 1 MB.');const data=envelope(JSON.parse(await file.text()));if(plan.steps.length&&!(await askConfirm('This file will replace the event and test settings shown. Save or download a copy first to keep unsaved work.','Open event file')))return;plan=data.plan;simulation=data.simulation;savedSignature=null;render();status('Editable event file opened. Choose Save in this browser to keep this copy here.');}catch(err){status('Could not open this event file. Choose a Rehearsal editable event (.json), not an HTML run sheet or PDF. Your current event is unchanged. '+err.message);}finally{e.target.value='';}};
render();
